use std::fs

fn find(ks: Vec<int>, k: int) -> int {
    let mut i = 0
    while i < ks.len() as int {
        if ks[i] == k { return i }
        i += 1
    }
    -1
}

fn main() {
    let text = fs::read_to_string("/dev/stdin").unwrap_or("")
    let mut ks: Vec<int> = []
    let mut vs: Vec<int> = []
    let mut cap = 0
    let mut first = true
    for line in text.lines() {
        let parts: Vec<string> = line.split_whitespace().collect()
        if parts.len() == 0 { continue }
        if first {
            cap = parts[0].parse::<int>().unwrap_or(1)
            first = false
            continue
        }
        let cmd = parts[0]
        if cmd == "put" {
            let k = parts[1].parse::<int>().unwrap_or(0)
            let v = parts[2].parse::<int>().unwrap_or(0)
            let i = find(ks, k)
            if i >= 0 {
                ks.remove(i as usize)
                vs.remove(i as usize)
            }
            ks.insert(0, k)
            vs.insert(0, v)
            if ks.len() as int > cap {
                let last = ks.len() - 1
                println("evict ${ks[last]}")
                ks.remove(last)
                vs.remove(last)
            }
        } else if cmd == "get" {
            let k = parts[1].parse::<int>().unwrap_or(0)
            let i = find(ks, k)
            if i < 0 {
                println("-1")
            } else {
                let v = vs[i as usize]
                ks.remove(i as usize)
                vs.remove(i as usize)
                ks.insert(0, k)
                vs.insert(0, v)
                println("${v}")
            }
        } else if cmd == "keys" {
            if ks.len() == 0 {
                println("<empty>")
            } else {
                let mut s = ""
                let mut j = 0
                while j < ks.len() as int {
                    if j > 0 { s = s + " " }
                    s = s + "${ks[j as usize]}"
                    j += 1
                }
                println(s)
            }
        }
    }
}

